    technique_http_desc: 'Em conexões HTTP sem criptografia, o cabeçalho "Host:" é reescrito como "hoSt:". Sistemas DPI simples que procuram o texto exato "Host:" deixam de encontrá-lo.',
    safetyTitle: 'Como ele se mantém seguro',
    safetyDesc: 'Por padrão, o Shroudly não precisa de driver nem de direitos de administrador: enquanto está ativo, ele apenas direciona o sistema para um proxy local e restaura a configuração anterior quando é parado, falha ou você encerra a sessão, para que sua conexão nunca fique quebrada. O modo Avançado é opcional e só é executado se você o ativar.',
