    technique_advanced: 'Modo Avançado (pacotes isca)',
    technique_advanced_desc: 'Contra a DPI que remonta as conexões (como no Irã ou na China), o Shroudly pode enviar uma cópia isca do primeiro pacote que o filtro lê, mas que expira antes de chegar ao site. Disponível no Windows e no Linux, exige permissão de administrador e só funciona quando você o ativa.',
