    blockedNoticeAdvanced: 'Votre réseau bloque cela plus profondément que ne peut l’atteindre le mode normal. Le mode Avancé agit au niveau des paquets et passe généralement ; il demande les droits administrateur et annule tout à l’arrêt.',
    blockedNoticeNoAdvanced: 'Le mode Avancé n’est pas disponible sur ce système, il n’y a donc plus rien à essayer automatiquement. Le détail est dans l’onglet Journaux — nous l’envoyer est le plus rapide pour corriger cela.',
    blockedNoticeOpenSettings: 'Ouvrir les réglages',
    blockedNoticeOpenLogs: 'Ouvrir les journaux',
    restartAppsTitle: '{apps} doit être redémarré',
    restartAppsBody: 'Un programme lit les réglages de connexion une seule fois, à son ouverture. {apps} tournait déjà : il utilise donc encore la connexion non protégée de son démarrage. Fermez-le complètement puis rouvrez-le.',
    resetToDefault: 'Réinitialiser',
    routeAppliesNow: 'Les changements de routage s’appliquent immédiatement.',
    obTitle1: 'Bienvenue dans Shroudly',
    obBody1: 'Quand un site est bloqué, votre opérateur le repère en général au nom du site dans votre tout premier paquet, ou en répondant à votre requête DNS par un mensonge. Shroudly remodèle ce paquet et résout les noms via un DNS chiffré : le site s’ouvre normalement. Votre trafic va toujours directement au site — ce n’est pas un VPN et cela ne cache pas qui vous êtes.',
    obTitle2: 'Un seul bouton',
    obBody2: 'Appuyez sur Démarrer : Shroudly dirige votre système vers lui le temps de son fonctionnement. Appuyez sur Arrêter : vos réglages réseau reviennent exactement comme avant — et ils sont restaurés même en cas de plantage, de fermeture forcée ou de coupure de courant. Vous n’avez jamais rien à défaire à la main.',
    obTitle3: 'Quels sites passent par lui',
    obBody3: 'Par défaut, tous les sites passent par Shroudly, et un site qui n’est pas bloqué est transmis tel quel : rien ne ralentit, et un site bloqué fonctionne même si vous n’en avez jamais entendu parler. Dans les Réglages, vous pouvez restreindre cela à une liste de sites, et y ajouter ou retirer des sites quand vous le souhaitez.',
    obTitle4: 'Si un site ne s’ouvre toujours pas',
    obBody4: 'Ouvrez les Réglages et lancez le test de site : il essaie réellement d’y accéder et vous dit ce qui le bloque. L’onglet Journaux note ce qui s’est passé pour chaque site, et c’est précisément ce dont nous avons besoin si vous signalez un problème. Sur Windows et Linux, il existe aussi un mode Avancé pour les réseaux que le mode normal ne franchit pas.',
    obTitle5: 'Si vous devez nous écrire',
    obBody5: 'Cet onglet note ce que Shroudly a fait : votre système, votre réseau et, pour chaque site, la technique qui a marché ou le nombre essayé avant d’abandonner. Si quelque chose ne fonctionne pas, copiez ce qui s’y trouve et envoyez-le avec votre signalement : en général cela répond à la question tout seul, sans échanges.',
